"""Arma build/arnes.html (el juego con ganchos de prueba en window.__dd) y build/arnes-bots.html (además, el bot de balance).
Uso: python3 tests/arnes.py  (antes: node tools/build.mjs)"""
import os,subprocess,sys
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from comun import ROOT,BUILD
src=sys.argv[1] if len(sys.argv)>1 else os.path.join(ROOT,'dist','distrito-domo.html')
arnes=os.path.join(BUILD,'arnes.html')
subprocess.check_call([sys.executable,os.path.join(ROOT,'tests','arnes_base.py'),src,arnes])
s=open(arnes).read()
s=s.replace("window.__dd={","window.__dd={"+open(os.path.join(ROOT,'tests','datos','poses.js')).read().strip()+"get DIST(){return DIST},carShot:(col,m,dir,nb)=>carSprite(col,m,dir,nb).c.toDataURL(),setRasca:v=>{RASCA2=v;SPR.clear();LASTSPR.clear()},setKit:v=>{KIT=v;SPR.clear();LASTSPR.clear()},VER,avanceTxt:()=>avanceTxt(),hitosStep:()=>hitosStep(),say:(t,n,o)=>say(t,n,o),get msgQ(){return msgQ},get cur(){return cur},get curO(){return curO},complaint:g=>[complaint(g),CTAB],get HINT(){return HINT},get GUIA(){return GUIA},guiaStep:d=>guiaStep(d),CLOUD,setAuto:v=>{AUTOLOW=v},lowQ:()=>lowQ(),get WBUD(){return WBUD},tabMsg:t=>tabForMsg(t),tabOfK:k=>tabOf(k),prof:{satCalc:()=>satCalc(),tick:d=>tick(d,true),ser:()=>JSON.stringify(serialize()).length,render:()=>render(),traffic:()=>trafficStep(),walk:d=>updWalkers(d),clearSpr:()=>{SPR.clear();LASTSPR.clear()},get stat(){return SPRSTAT},get cap(){return [OBJN,sprCap()]},get n(){let a=0;for(const m of SPRL.values())a+=m.size;return {sprl:a,last:LASTSPR.size,outc:OUTC.size,cars:CARS.length,walkers:walkers.length,extra:EXTRA.length,res:RES,autolow:AUTOLOW,fta:FTA}}},PARCELS,whatName:t=>whatName(t),goDist:d=>goDist(d),mis:id=>{const m=MISI[id];return {txt:m.txt,prog:m.prog?m.prog():null,goal:m.goal}},rioval:v=>{if(v!=null)RIOVAL=v;return RIOVAL},newG:()=>{S=newGame();recompute();return stats.sat},get W(){return walkers},get EX(){return EXTRA},get VOZ(){return VOZ},get FOLLOW(){return FOLLOW},vozOpen:w=>vozOpen(w),get FUT(){return FUT},get WSPRn(){return WSPR.size},get FW(){return FW},setFW:n=>{for(let k=0;k<n;k++)FW.push({x:0,y:0,vx:0,vy:0,l:3,c:'#fff'})},rioFase:()=>rioFase(),rioStep:(dt,q)=>rioStep(dt,q),rioW:()=>rioW(),cxR:y=>cxR(y),distUI:()=>distUI(),bolt:()=>{BOLT={t:0,...mkBolt()};BOLTN=99},fotoOn:()=>fotoOn(),fotoOff:()=>fotoOff(),tlStart:o=>tlStart(o),tlStop:()=>tlStop(),get TL(){return TL&&{k:TL.k,n:TL.fr.length,t:TL.t,dur:TL.dur}},get PHOTO(){return PHOTO},get REAL(){return !!REAL},histSnap:()=>{histLoad();histSnap()},get HIST(){return HIST&&{n:HIST.f.length,iv:HIST.iv,id:HIST.id}},get CARS(){return CARS},camTo:(i,d)=>camTo(i,d),momento:i=>momento(i),zoomAt:(z,x,y)=>zoomAt(z,x,y),get ZA(){return ZA},get CAMG(){return CAMG},get TS(){return TS},get CINE(){return CINE},get INER(){return INER},get pan(){return [panX,panY]},get ROT(){return ROT},turn:d=>turn(d),misProg:id=>misProg(MISI[id]),bizStreet:()=>bizStreet(),greenCnt:()=>greenCnt(),greenStreets:()=>greenStreets(),get FWn(){return FW.length},get DAY(){return DAY},flashAt:(i,d)=>flashAt(i,d),confetti:(i,n)=>confetti(i,n),",1)
# v85: el nombramiento se firma solo en las pruebas (las que lo revisan ponen window.__ofAuto=false antes de cargar)
assert "function oficio(nm,done){" in s
s=s.replace("function oficio(nm,done){","function oficio(nm,done){if(window.__ofAuto!==false){done(nm);return}",1)
open(arnes,'w').write(s)
a="window.claude?.hot?.snapshot?.("
bot=open(os.path.join(ROOT,'tests','bots','bot.js')).read()
open(os.path.join(BUILD,'arnes-bots.html'),'w').write(s.replace(a,bot+"\n"+a,1))
print('listo: build/arnes.html y build/arnes-bots.html')
